<div class="grid two"><section class="card"><h2>Incoming and active orders</h2>@forelse($orders as $order)<article style="padding:14px 0;border-bottom:1px solid var(--line)"><div style="display:flex;justify-content:space-between"><b>{{ $order->tableSession->diningTable->table_code }} · {{ $order->order_number }}</b><span class="pill {{ $order->status }}">{{ $order->status }}</span></div><ul>@foreach($order->items as $item)<li>{{ $item->quantity }} × {{ $item->item_name_snapshot }} @if($item->special_instruction)<b>— {{ $item->special_instruction }}</b>@endif</li>@endforeach</ul>@if($order->customer_note)<p><b>Note:</b> {{ $order->customer_note }}</p>@endif @if($order->status==='pending')<div class="actions"><form method="post" action="/counter/orders/{{ $order->id }}/confirm">@csrf<button>Confirm & unlock games</button></form><form class="row" method="post" action="/counter/orders/{{ $order->id }}/reject">@csrf<input name="reason" placeholder="Required rejection reason" required><button class="warn">Reject</button></form></div>@endif</article>@empty<p class="muted">No active orders.</p>@endforelse</section>
<aside><section class="card"><h2>Service requests</h2>@forelse($requests as $request)<div style="padding:10px 0;border-bottom:1px solid var(--line)"><b>{{ $request->tableSession->diningTable->table_code }}</b> · {{ str_replace('_',' ',$request->request_type) }}<br><span class="muted">{{ $request->message }}</span><form class="row" method="post" action="/counter/requests/{{ $request->id }}">@csrf<select name="status"><option value="acknowledged">Acknowledge</option><option value="completed">Complete</option><option value="cancelled">Cancel</option></select><button>Update</button></form></div>@empty<p class="muted">All clear.</p>@endforelse</section><section class="card"><h2>Game sessions</h2>@forelse($games as $game)<div style="padding:10px 0;border-bottom:1px solid var(--line)"><b>{{ $game->tableSession->diningTable->table_code }}</b> · expires {{ $game->expires_at->format('H:i:s') }}<div class="actions"><form class="row" method="post" action="/counter/games/{{ $game->id }}/extend">@csrf<input type="number" name="minutes" value="15" min="1" max="240" style="width:75px"><button>Extend</button></form><form method="post" action="/counter/games/{{ $game->id }}/stop">@csrf<button class="warn">Stop</button></form></div></div>@empty<p class="muted">No games unlocked.</p>@endforelse</section></aside></div>
<section class="card"><h2>Billing</h2><table><tr><th>Table/session</th><th>Orders</th><th>Subtotal</th><th>Status</th><th>Action</th></tr>@foreach($sessions as $session)<tr><td><b>{{ $session->diningTable->table_code }}</b><br>{{ $session->session_code }}</td><td>{{ $session->orders->count() }}</td><td>₹{{ number_format($session->orders->whereNotIn('status',['cancelled','rejected'])->sum('total_amount'),2) }}</td><td><span class="pill {{ $session->status }}">{{ $session->status }}</span></td><td>@if(!$session->bill)<form class="row" method="post" action="/counter/sessions/{{ $session->id }}/bill">@csrf<input type="number" step="0.01" name="discount_amount" value="0" min="0" style="width:100px"><button>Generate bill</button></form>@elseif($session->bill->payment_status==='unpaid')<div><b>{{ $session->bill->bill_number }} · ₹{{ $session->bill->grand_total }}</b><form class="row" method="post" action="/counter/bills/{{ $session->bill->id }}/pay">@csrf<input type="number" step="0.01" name="received_amount" min="{{ $session->bill->grand_total }}" placeholder="Cash received" required><button>Record cash</button></form></div>@else<span class="pill">paid</span>@endif @if($session->bill)<a href="/counter/bills/{{ $session->bill->id }}/receipt" target="_blank">Receipt</a>@endif</td></tr>@endforeach</table></section>@endsection
